'use strict';
// Server data is authoritative; no accounts or schedules are shipped in the client.
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let accounts=[];
const kinds={first:'1차 합격자 발표',interview:'면접',final:'최종 합격자 발표',lesson:'방과후 수업'};
let events=[];
let user=null,role='',identity='',tab='calendar',selected='',month=new Date().getMonth(),year=new Date().getFullYear();
const current=()=>accounts.find(a=>a.id===identity);
const visibleStudents=()=>accounts.filter(a=>a.role==='학생'&&(role==='관리자'||(role==='학생'?a.id===identity:a.class===current()?.class)));
const visibleEvents=()=>events.filter(e=>e.type==='lesson'?(role==='관리자'||e.class===current()?.class):visibleStudents().some(s=>s.id===e.student));
const sorted=a=>[...a].sort((a,b)=>(a.date+' '+a.time).localeCompare(b.date+' '+b.time));
const label=e=>e.type==='lesson'?e.title:`${e.univ} · ${kinds[e.type]}`;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200);}
function showModal(title,body,foot=''){const d=$('#modal');d.innerHTML=`<div class="card-head"><h2>${title}</h2><button onclick="document.querySelector('#modal').close()" aria-label="닫기">✕</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;if(!d.open)d.showModal();}
function render(){const students=visibleStudents(),ve=visibleEvents(),me=current();if(!students.some(a=>a.id===selected))selected=students[0]?.id||'';
$('#app').innerHTML=`<aside><div class="brand"><span>m</span>면접온</div><div class="subtitle">면접 방과후 운영 공간</div><div class="nav-title">WORKSPACE</div><button class="nav ${tab==='calendar'?'active':''}" data-tab="calendar">▦ &nbsp; ${role==='학생'?'나의 달력':'달력'}</button>${role!=='학생'?`<button class="nav ${tab==='students'?'active':''}" data-tab="students">♙ &nbsp; 학생</button><button class="nav ${tab==='accounts'?'active':''}" data-tab="accounts">⊞ &nbsp; 계정 관리</button>`:''}<div class="aside-bottom"><span class="avatar">${role==='관리자'?'관':esc(me?.name[0])}</span>${role==='관리자'?'관리자':esc(me?.name)}<p>${role==='관리자'?'전체 반 관리':esc(me?.class)} · ${role}</p></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">면접 방과후 &nbsp; / &nbsp; <strong>${role} 공간</strong></div><div class="demo"><span>${esc(me?.name)} · ${esc(role)}</span><button id="changePassword">비밀번호 변경</button><button id="logout">로그아웃</button></div></header><main><div class="heading"><div><h1>${tab==='calendar'?(role==='학생'?'나의 면접 일정':'우리 반 일정'):tab==='students'?'학생별 대학 일정':'계정 관리'}</h1><p class="muted">${tab==='accounts'?(role==='관리자'?'교사와 학생 계정을 한 번에 등록하세요.':`${esc(me?.class)} 학생 계정을 등록하세요.`):role==='학생'?'대학 일정과 방과후 준비 과제를 함께 확인하세요.':`${role==='관리자'?'전체 반':esc(me?.class)}의 면접 준비를 한눈에 확인하세요.`}</p></div>${tab!=='accounts'&&role!=='학생'?'<div class="actions"><button id="addUniversity">＋ 대학 일정 등록</button><button class="primary" id="addLesson">＋ 방과후 수업 등록</button></div>':''}</div>${tab==='accounts'?accountsView():`${stats(students,ve)}${tab==='students'?timelineView(students):calendarView(ve)}`}<p class="notice">등록한 계정과 일정은 저장되며, 배정된 권한에 따라 표시됩니다.</p></main></div>`;
$('#logout').onclick=logout;$('#changePassword').onclick=()=>passwordForm();if($('#addUniversity'))$('#addUniversity').onclick=()=>universityForm();document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});if($('#addLesson'))$('#addLesson').onclick=()=>lessonForm();if($('#student'))$('#student').onchange=e=>{selected=e.target.value;render();};if($('#prev'))$('#prev').onclick=()=>changeMonth(-1);if($('#next'))$('#next').onclick=()=>changeMonth(1);if($('#resetMonth'))$('#resetMonth').onclick=()=>{month=new Date().getMonth();year=new Date().getFullYear();render();};document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>detail(b.dataset.event));if($('#template'))$('#template').onclick=downloadTemplate;if($('#upload'))$('#upload').onchange=upload;if($('#manual'))$('#manual').onclick=manual;document.querySelectorAll('.reset-password').forEach(b=>b.onclick=()=>resetPassword(b.dataset.id));
}
function stats(students,ve){const monthly=ve.filter(e=>e.date.startsWith(`${year}-${String(month+1).padStart(2,'0')}`));return `<div class="stats"><div class="stat"><label>${role==='학생'?'지원 대학':'배정 학생'}</label><strong>${role==='학생'?new Set(ve.filter(e=>e.univ).map(e=>e.univ)).size:students.length}<small>${role==='학생'?'개교':'명'}</small></strong></div><div class="stat"><label>${month+1}월 면접 일정</label><strong>${monthly.filter(e=>e.type==='interview').length}<small>건</small></strong></div><div class="stat accent"><label>${month+1}월 방과후 수업</label><strong>${monthly.filter(e=>e.type==='lesson').length}<small>회</small></strong></div></div>`;}
function changeMonth(n){const d=new Date(year,month+n,1);year=d.getFullYear();month=d.getMonth();render();}
function calendarView(ve){const start=new Date(year,month,1),offset=start.getDay(),count=Math.ceil((offset+new Date(year,month+1,0).getDate())/7)*7;let cells='';for(let i=0;i<count;i++){const d=new Date(year,month,i-offset+1),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,es=sorted(ve.filter(e=>e.date===key));cells+=`<div class="day ${d.getMonth()!==month?'outside':''}"><span class="date">${d.getDate()}</span>${es.map(e=>`<button class="event ${e.type}" data-event="${esc(e.id)}">${e.type==='lesson'?'방과후 · '+esc(e.time):role==='학생'?esc(e.time):esc(accounts.find(a=>a.id===e.student)?.name)}<br>${esc(e.type==='lesson'?e.title:e.univ+' '+(e.type==='first'?'1차 발표':e.type==='final'?'최종 발표':'면접'))}</button>`).join('')}</div>`;}return `<div class="workspace"><section class="card"><div class="card-head"><div class="month-controls"><h2>${year}년 ${month+1}월</h2><button id="prev" aria-label="이전 달">‹</button><button id="next" aria-label="다음 달">›</button></div><button id="resetMonth">이번 달</button></div><div class="legend">${Object.entries(kinds).map(([k,v])=>`<span><i class="${k}"></i>${v}</span>`).join('')}</div><div class="calendar-box"><div class="week">${['일','월','화','수','목','금','토'].map(d=>`<div>${d}</div>`).join('')}</div><div class="calendar">${cells}</div></div></section>${sideView(ve)}</div>`;}
function sideView(ve){const lessons=sorted(ve.filter(e=>e.type==='lesson'&&e.date.startsWith(`${year}-${String(month+1).padStart(2,'0')}`))),l=lessons[0],interviews=sorted(ve.filter(e=>e.type==='interview'&&e.date.startsWith(`${year}-${String(month+1).padStart(2,'0')}`)));return `<section class="card side-card"><div class="side-content"><div class="eyebrow">AFTER SCHOOL</div><h2 style="margin-top:9px">이번 달 방과후</h2>${l?`<div class="next-lesson"><span class="pill" style="background:#ffebc7;color:#946724">${esc(l.class)}</span><h3>${esc(l.title)}</h3><p class="muted">${esc(l.date.slice(5).replace('-','월 '))}일 · ${esc(l.time)}</p><button data-event="${esc(l.id)}">준비 과제 확인하기 →</button></div>`:'<p class="muted">등록된 수업이 없습니다.</p>'}<h2 style="margin-top:28px">${month+1}월 면접</h2>${interviews.slice(0,5).map(e=>`<div class="list-item"><span class="avatar">${Number(e.date.slice(-2))}</span><div>${esc(e.univ)}<small>${esc(accounts.find(a=>a.id===e.student)?.name)} · ${esc(e.time)}</small></div></div>`).join('')||'<p class="muted">면접 일정이 없습니다.</p>'}</div></section>`;}
function timelineView(students){const es=sorted(events.filter(e=>e.student===selected)),univs=[...new Set(es.map(e=>e.univ))],dates=[...new Set(es.map(e=>e.date))];return `<section class="card"><div class="card-head"><div><h2>대학별 일정 흐름</h2><p class="muted" style="margin:6px 0 0">위에서 아래로 날짜순 · 대학별 발표와 면접을 연결해 확인하세요.</p></div><select id="student" class="student-picker" aria-label="학생 선택">${students.map(s=>`<option value="${esc(s.id)}" ${selected===s.id?'selected':''}>${esc(s.number)} ${esc(s.name)}</option>`).join('')}</select></div>${es.length?`<div class="timeline-wrap"><div class="timeline" style="grid-template-columns:90px repeat(${univs.length},minmax(180px,1fr))"><div class="th">날짜</div>${univs.map(u=>`<div class="th">${esc(u)}<div class="muted" style="margin-top:8px;font-size:12px">${esc(es.find(e=>e.univ===u).major)}</div></div>`).join('')}${dates.map(d=>`<div class="time-date">${Number(d.slice(5,7))}월 ${Number(d.slice(8))}일</div>${univs.map(u=>{const ue=es.filter(e=>e.univ===u),active=d>=ue[0].date&&d<=ue[ue.length-1].date;return `<div class="timeline-cell ${active?'link':''}">${ue.filter(e=>e.date===d).map(e=>`<button class="milestone ${e.type}" data-event="${esc(e.id)}">${kinds[e.type]}<small>${e.time}</small></button>`).join('')}</div>`;}).join('')}`).join('')}</div></div>`:'<div class="empty">이 학생에게 등록된 대학 일정이 없습니다.</div>'}</section>`;}
function detail(id){const e=visibleEvents().find(e=>e.id===id);if(!e)return;showModal(e.type==='lesson'?'방과후 수업 · 준비 과제':kinds[e.type],`<span class="pill">${e.type==='lesson'?esc(e.class):esc(accounts.find(a=>a.id===e.student)?.name)}</span><h2 style="margin:18px 0 10px">${esc(e.type==='lesson'?e.title:e.univ+' '+e.major)}</h2><p>${esc(e.date)} &nbsp; ${esc(e.time)}</p>${e.type==='lesson'?`<h3 style="font-size:15px;margin-top:24px">수업 전 준비할 과제</h3><div class="task">${esc(e.task||'등록된 과제가 없습니다.')}</div>`:''}`,role!=='학생'?'<button id="deleteEvent">일정 삭제</button><button class="primary" id="editEvent">수정</button>':'');if($('#editEvent'))$('#editEvent').onclick=()=>e.type==='lesson'?lessonForm(e):universityForm(e);if($('#deleteEvent'))$('#deleteEvent').onclick=()=>deleteEvent(e);}

function lessonForm(existing){if(role==='학생')return;if(!accounts.some(a=>a.class)){toast('계정 관리에서 교사 또는 학생 계정을 먼저 등록해주세요.');return;}const classes=role==='관리자'?[...new Set(accounts.map(a=>a.class).filter(Boolean))]:[current().class];showModal(existing?'방과후 수업 수정':'방과후 수업 등록',`<form id="lessonForm"><input type="hidden" name="type" value="lesson"><label>배정반<select name="class">${classes.map(c=>`<option ${existing?.class===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>수업명<input name="title" required maxlength="80" value="${esc(existing?.title||'')}"></label><div class="actions"><label>날짜<input type="date" name="date" required value="${existing?.date||localDate()}"></label><label>시간<input type="time" name="time" required value="${existing?.time||'16:30'}"></label></div><label>준비 과제<textarea name="task" maxlength="5000" placeholder="학생들이 수업 전에 준비할 내용을 적어주세요.">${esc(existing?.task||'')}</textarea></label><button class="primary" type="submit">${existing?'수정 저장':'수업 등록'}</button></form>`);$('#lessonForm').onsubmit=ev=>{ev.preventDefault();saveEvent(ev.target,existing);};}

function accountsView(){const list=accounts.filter(a=>a.role!=='관리자'&&(role==='관리자'||(a.role==='학생'&&a.class===current()?.class)));return `<section class="card"><div class="card-head"><h2>${role==='관리자'?'전체 계정':'우리 반 학생 계정'} <span class="pill">${list.length}명</span></h2><button id="manual">＋ 직접 입력</button></div><div class="upload-box"><h3>엑셀 파일로 계정 일괄 등록</h3><p class="muted">학번 · 이름 · 권한 · 배정반 · 아이디<br>${role==='관리자'?'권한은 교사 또는 학생으로 선택할 수 있습니다.':`${esc(current()?.class)}의 학생만 등록할 수 있습니다.`}</p><div class="actions" style="justify-content:center"><button id="template">↓ 엑셀 양식 다운로드</button><label class="primary" style="padding:10px 15px;border-radius:9px;cursor:pointer">↑ 엑셀 업로드<input id="upload" type="file" accept=".xlsx" style="display:none"></label></div><p class="muted" style="font-size:12px">.xlsx · 최대 5MB / 500명 · 업로드 후 오류와 등록 내용을 확인합니다.</p></div><div class="table-wrap"><table><thead><tr>${['학번','이름','권한','배정반','아이디','비밀번호'].map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${list.map(a=>`<tr><td>${esc(a.number||'—')}</td><td><strong>${esc(a.name)}</strong></td><td><span class="pill">${esc(a.role)}</span></td><td>${esc(a.class)}</td><td>${esc(a.id)}</td><td><button class="reset-password" data-id="${esc(a.id)}">초기화</button></td></tr>`).join('')}</tbody></table></div></section>`;}
async function downloadTemplate(){try{const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet('계정 등록');ws.columns=[{header:'학번',key:'number',width:16},{header:'이름',key:'name',width:18},{header:'권한',key:'role',width:14},{header:'배정반',key:'class',width:20},{header:'아이디',key:'id',width:24}];ws.views=[{state:'frozen',ySplit:1}];ws.getRow(1).eachCell(c=>{c.font={bold:true,color:{argb:'FFFFFFFF'}};c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF365BEA'}};});for(let r=2;r<=501;r++){ws.getCell(`A${r}`).numFmt='@';ws.getCell(`E${r}`).numFmt='@';ws.getCell(`C${r}`).dataValidation={type:'list',allowBlank:false,formulae:[role==='관리자'?'"교사,학생"':'"학생"'],showErrorMessage:true,errorTitle:'권한을 확인하세요',error:'목록에서 권한을 선택해주세요.',errorStyle:'stop'};if(role==='교사'){ws.getCell(`C${r}`).value='학생';ws.getCell(`D${r}`).value=current().class;ws.getCell(`D${r}`).dataValidation={type:'list',formulae:[`"${current().class}"`],showErrorMessage:true,error:'본인 배정반만 선택할 수 있습니다.',errorStyle:'stop'};}}const blob=new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='면접온_계정등록양식.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast('양식을 준비하지 못했습니다. 다시 시도해주세요.');}}
function validateRows(rows){const ids=new Set(accounts.map(a=>a.id)),numbers=new Set(accounts.filter(a=>a.role==='학생').map(a=>a.number));return rows.map((a,i)=>{let error='';if(!a.name||!a.role||!a.class||!a.id)error='필수 항목 누락';else if(!['교사','학생'].includes(a.role))error='권한은 교사 또는 학생';else if(a.role==='학생'&&!a.number)error='학생 학번 필수';else if(role==='학생'||(role==='교사'&&(a.role!=='학생'||a.class!==current().class)))error='본인 배정반의 학생만 등록 가능';else if(!/^[a-zA-Z0-9._-]{3,40}$/.test(a.id))error='아이디: 영문·숫자·._- 3~40자';else if(ids.has(a.id))error='중복 아이디';else if(a.role==='학생'&&numbers.has(a.number))error='중복 학번';ids.add(a.id);if(a.role==='학생')numbers.add(a.number);return {...a,row:a.row||i+2,error};});}
async function upload(ev){const file=ev.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('5MB 이하 파일을 선택해주세요.');return;}try{const wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());const ws=wb.worksheets[0];if(!ws)throw Error('빈 파일입니다.');const headers=['학번','이름','권한','배정반','아이디'];if(headers.some((h,i)=>ws.getRow(1).getCell(i+1).text.trim()!==h))throw Error('첫 행의 열을 학번, 이름, 권한, 배정반, 아이디 순으로 맞춰주세요.');const rows=[];ws.eachRow((r,n)=>{if(n===1)return;const v=[1,2,3,4,5].map(i=>r.getCell(i).text.trim());if(!v[0]&&!v[1]&&!v[4])return;rows.push({number:v[0],name:v[1],role:v[2],class:v[3],id:v[4],row:n});});if(!rows.length)throw Error('등록할 계정이 없습니다.');if(rows.length>500)throw Error('한 번에 최대 500명까지 등록할 수 있습니다.');previewRows(rows);}catch(e){toast(e.message||'엑셀 파일을 읽지 못했습니다.');}ev.target.value='';}
async function previewRows(rows){let checked;try{checked=(await api('/api/accounts/validate',{method:'POST',body:{rows}})).rows;}catch(e){toast(e.message);return;}const errors=checked.filter(r=>r.error);showModal('계정 등록 미리보기',`<p>${checked.length}명 중 <strong>${errors.length}명 오류</strong> ${errors.length?'· 파일을 수정한 후 다시 업로드해주세요.':'· 아래 계정을 등록할 수 있습니다.'}</p><div class="table-wrap"><table><thead><tr><th>행</th><th>이름</th><th>권한 / 반</th><th>아이디</th><th>검사</th></tr></thead><tbody>${checked.map(a=>`<tr><td>${a.row}</td><td>${esc(a.name)}</td><td>${esc(a.role)} / ${esc(a.class)}</td><td>${esc(a.id)}</td><td class="${a.error?'error':''}">${esc(a.error||'정상')}</td></tr>`).join('')}</tbody></table></div>`,`<button onclick="document.querySelector('#modal').close()">닫기</button>${!errors.length?'<button class="primary" id="confirmImport">계정 등록</button>':''}`);if($('#confirmImport'))$('#confirmImport').onclick=async()=>{const button=$('#confirmImport');button.disabled=true;button.textContent='등록 중…';try{const result=await api('/api/accounts',{method:'POST',body:{rows}});await refreshState();showCredentials(result.credentials);}catch(e){toast(e.message);button.disabled=false;button.textContent='계정 등록';}};}

function manual(){showModal('계정 직접 입력',`<form id="accountForm"><label>학번<input name="number" placeholder="학생 필수 / 교사 생략 가능"></label><label>이름<input name="name" required></label><label>권한<select name="role">${(role==='관리자'?['학생','교사']:['학생']).map(r=>`<option>${r}</option>`).join('')}</select></label><label>배정반${role==='교사'?`<input name="class" value="${esc(current().class)}" readonly>`:'<input name="class" required placeholder="예: 면접 A반">'}</label><label>아이디<input name="id" required placeholder="영문·숫자·._- 3~40자"></label><button type="submit" class="primary">등록 내용 확인</button></form>`);$('#accountForm').onsubmit=e=>{e.preventDefault();previewRows([Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,v.trim()]))]);};}
boot();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_visible_interview_schedule',description:'현재 로그인한 계정에 허용된 대학 일정과 방과후 수업을 서버에서 조회합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw Error('입력 항목이 없어야 합니다.');const state=await api('/api/state');return {role:state.user.role,events:state.events};}});}catch(e){console.warn('WebMCP unavailable');}}

function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
async function api(url,{method='GET',body}={}){
 let response;try{response=await fetch(url,{method,credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json','X-Interview-Request':'1'}:{},...(body?{body:JSON.stringify(body)}:{})});}catch{throw Error('서버에 연결하지 못했습니다. 연결 상태를 확인한 후 다시 시도해주세요.');}
 const data=await response.json();if(!response.ok){if(response.status===401&&url!=='/api/login'){user=null;accounts=[];events=[];$('#modal').close();loginView();}throw Object.assign(Error(data.error||'요청을 처리하지 못했습니다.'),{status:response.status,details:data});}return data;
}
async function boot(){
 $('#app').innerHTML='<div class="login-layout"><div class="login-card"><div class="brand"><span>m</span>면접온</div><p role="status">로그인 상태를 확인하고 있습니다…</p></div></div>';
 try{const result=await api('/api/me');user=result.user;if(user.mustChangePassword){passwordForm(true);return;}await refreshState();}catch(e){if(e.status===401)loginView();else loginView(e.message);}
}
async function refreshState(){const data=await api('/api/state');user=data.user;role=user.role;identity=user.id;accounts=data.accounts;events=data.events;render();}
function loginView(message=''){
 $('#app').innerHTML=`<div class="login-layout"><section class="login-intro"><div class="brand"><span>m</span>면접온</div><h1>한 명의 일정부터,<br>우리 반의 면접 준비까지.</h1><p>대학별 일정과 방과후 수업을<br>하나의 공간에서 관리하세요.</p><div class="login-path"><span>1차 발표</span><i></i><span>면접</span><i></i><span>최종 발표</span></div></section><section class="login-card"><div class="eyebrow">INTERVIEW AFTER SCHOOL</div><h2>로그인</h2><p class="muted">발급받은 계정으로 접속해주세요.</p><form id="loginForm"><label>아이디<input name="id" required autocomplete="username" maxlength="40" placeholder="아이디 입력"></label><label>비밀번호<input name="password" type="password" required autocomplete="current-password" maxlength="128" placeholder="비밀번호 입력"></label><p class="error" id="loginError" role="alert">${esc(message)}</p><button class="primary" type="submit">로그인</button></form><p class="muted login-help">계정이나 비밀번호를 잊었다면<br>담당 교사 또는 관리자에게 문의하세요.</p></section></div>`;
 $('#loginForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;button.textContent='로그인 중…';$('#loginError').textContent='';try{const data=Object.fromEntries(new FormData(e.target));const result=await api('/api/login',{method:'POST',body:data});user=result.user;tab='calendar';selected='';if(user.mustChangePassword)passwordForm(true);else await refreshState();}catch(error){$('#loginError').textContent=error.message;button.disabled=false;button.textContent='로그인';}};
}
async function logout(){try{await api('/api/logout',{method:'POST',body:{}});user=null;accounts=[];events=[];role='';identity='';$('#modal').close();loginView();}catch(e){toast(e.message);}}
function passwordForm(required=false){
 const form=`<p class="muted">${required?'첫 로그인입니다. 발급받은 임시 비밀번호를 본인 비밀번호로 변경해주세요.':'현재 비밀번호를 확인하고 새 비밀번호로 변경합니다.'}</p><form id="passwordForm"><label>현재 ${required?'임시 ':''}비밀번호<input type="password" name="currentPassword" autocomplete="current-password" maxlength="128" required></label><label>새 비밀번호<input type="password" name="newPassword" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="8자 이상"></label><label>새 비밀번호 확인<input type="password" name="confirmPassword" autocomplete="new-password" minlength="8" maxlength="128" required></label><p class="error" id="passwordError" role="alert"></p><button class="primary" type="submit">비밀번호 변경</button></form>`;
 if(required){$('#app').innerHTML=`<div class="login-layout single"><section class="login-card"><div class="brand"><span>m</span>면접온</div><h2>비밀번호 설정</h2>${form}<button id="backLogout" style="margin-top:16px">로그아웃</button></section></div>`;$('#backLogout').onclick=logout;}else showModal('비밀번호 변경',form);
 $('#passwordForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(data.newPassword!==data.confirmPassword){$('#passwordError').textContent='새 비밀번호가 일치하지 않습니다.';return;}const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/password',{method:'POST',body:data});$('#modal').close();await refreshState();toast('비밀번호를 변경했습니다.');}catch(error){if($('#passwordError'))$('#passwordError').textContent=error.message;button.disabled=false;}};
}
async function saveEvent(form,existing){const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));await api(existing?`/api/events/${existing.id}`:'/api/events',{method:existing?'PUT':'POST',body:data});year=Number(data.date.slice(0,4));month=Number(data.date.slice(5,7))-1;$('#modal').close();await refreshState();toast('일정을 저장했습니다.');}catch(e){toast(e.message);button.disabled=false;}}
function universityForm(existing){
 const students=visibleStudents();if(!students.length){toast('계정 관리에서 학생을 먼저 등록해주세요.');return;}if(role==='학생')return;
 showModal(existing?'대학 일정 수정':'대학 일정 등록',`<form id="universityForm"><label>학생<select name="student">${students.map(s=>`<option value="${esc(s.id)}" ${(existing?.student||selected)===s.id?'selected':''}>${esc(s.number)} ${esc(s.name)} · ${esc(s.class)}</option>`).join('')}</select></label><label>대학교<input name="univ" required maxlength="100" value="${esc(existing?.univ||'')}" placeholder="대학교명"></label><label>학과 / 전형<input name="major" maxlength="100" value="${esc(existing?.major||'')}" placeholder="예: 경영학과 · 학생부종합"></label><label>일정 종류<select name="type">${Object.entries(kinds).filter(([k])=>k!=='lesson').map(([k,v])=>`<option value="${k}" ${(existing?.type||'interview')===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="actions"><label>날짜<input type="date" name="date" min="2000-01-01" max="2100-12-31" required value="${existing?.date||localDate()}"></label><label>시간<input type="time" name="time" required value="${existing?.time||'09:00'}"></label></div><p class="muted">발표와 면접 일정을 각각 등록하면 학생 탭에서 연결됩니다. 1차 발표가 없는 전형은 면접부터 등록하세요.</p><button class="primary" type="submit">일정 저장</button></form>`);
 $('#universityForm').onsubmit=e=>{e.preventDefault();saveEvent(e.target,existing);};
}
function deleteEvent(event){showModal('일정 삭제',`<p><strong>${esc(label(event))}</strong><br>${esc(event.date)} ${esc(event.time)}</p><p>이 일정을 삭제하시겠습니까?</p>`,'<button id="cancelDelete">취소</button><button class="primary" id="confirmDelete">삭제</button>');$('#cancelDelete').onclick=()=>detail(event.id);$('#confirmDelete').onclick=async()=>{const button=$('#confirmDelete');button.disabled=true;try{await api(`/api/events/${event.id}`,{method:'DELETE',body:{}});$('#modal').close();await refreshState();toast('일정을 삭제했습니다.');}catch(e){toast(e.message);button.disabled=false;}};}
function showCredentials(credentials){
 showModal('계정 발급 완료',`<p>임시 비밀번호를 저장해 각 사용자에게 전달해주세요. 이 창을 닫으면 비밀번호를 다시 조회할 수 없으며, 계정 관리에서 재발급할 수 있습니다.</p><p class="muted">첫 로그인 시 새 비밀번호를 설정해야 합니다.</p><div class="table-wrap"><table><thead><tr><th>이름</th><th>아이디</th><th>임시 비밀번호</th></tr></thead><tbody>${credentials.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.id)}</td><td><code>${esc(a.password)}</code></td></tr>`).join('')}</tbody></table></div>`,'<button class="primary" id="downloadCredentials">발급 내역 엑셀 다운로드</button>');
 $('#downloadCredentials').onclick=async()=>{try{const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet('계정 발급 내역');ws.columns=[{header:'학번',key:'number',width:16},{header:'이름',key:'name',width:18},{header:'권한',key:'role',width:12},{header:'배정반',key:'class',width:20},{header:'아이디',key:'id',width:24},{header:'임시 비밀번호',key:'password',width:26}];ws.addRows(credentials);ws.getRow(1).font={bold:true};const blob=new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='면접온_계정발급내역.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast('파일을 만들지 못했습니다. 화면의 발급 정보를 확인해주세요.');}};
}
function resetPassword(id){const a=accounts.find(a=>a.id===id);if(!a)return;showModal('임시 비밀번호 재발급',`<p>${esc(a.name)} (${esc(a.id)})의 비밀번호를 초기화하시겠습니까?</p><p class="muted">기존 비밀번호와 로그인 세션이 만료되며 새 임시 비밀번호를 발급합니다.</p>`,'<button id="cancelReset">취소</button><button class="primary" id="confirmReset">임시 비밀번호 발급</button>');$('#cancelReset').onclick=()=>$('#modal').close();$('#confirmReset').onclick=async()=>{const button=$('#confirmReset');button.disabled=true;try{const result=await api('/api/accounts/reset-password',{method:'POST',body:{id}});showCredentials(result.credentials);}catch(e){toast(e.message);button.disabled=false;}};}
